/**
 * Core SMS message type stored in the local SQLite database.
 */
export interface SmsMessage {
  id: number;
  android_sms_id: string | null;
  sender: string;
  message: string;
  received_at: number; // Unix milliseconds
  message_type: string;
  created_at: number | null; // Unix seconds (SQLite default via strftime)
  fingerprint?: string | null;
}

/**
 * Payload used when inserting a new SMS message.
 * `id` and `created_at` are auto-generated by the database.
 */
export type InsertSmsPayload = Omit<SmsMessage, 'id' | 'created_at'>;

/**
 * Result returned by repository insert operations.
 */
export interface InsertResult {
  lastInsertRowId: number;
  changes: number;
}

/**
 * Lightweight summary of the database state for display.
 */
export interface DbStatus {
  initialized: boolean;
  smsCount: number;
  error: string | null;
}
